from __future__ import annotations
from dataclasses import dataclass
from typing import Any, Optional
from .node import VNode

@dataclass
class Patch:
    path: list[int]

@dataclass
class ReplaceNode(Patch):
    new_node: VNode

@dataclass
class UpdateProps(Patch):
    set_props: dict[str, Any]
    remove_props: list[str]

@dataclass
class InsertChild(Patch):
    index: int
    node: VNode

@dataclass
class RemoveChild(Patch):
    index: int

@dataclass
class ReorderChildren(Patch):
    moves: list[tuple[int, int]]  # (from_index, to_index)

def diff(old_tree: Optional[VNode], new_tree: Optional[VNode], path: Optional[list[int]] = None) -> list[Patch]:
    # STUB: Must recursively diff trees and generate patches
    path = path or []
    if old_tree is None and new_tree is not None:
        return [ReplaceNode(path=path, new_node=new_tree)]
    if old_tree is not None and new_tree is None:
        return [ReplaceNode(path=path, new_node=VNode())]
    return []

