from __future__ import annotations
from dataclasses import dataclass, field
from typing import Optional, Any

@dataclass
class VNode:
    tag: Optional[str] = None  # None for text nodes
    props: dict[str, Any] = field(default_factory=dict)
    children: list[VNode] = field(default_factory=list)
    key: Optional[str] = None
    text: Optional[str] = None

    def clone(self) -> VNode:
        return VNode(
            tag=self.tag,
            props=dict(self.props),
            children=[c.clone() for c in self.children],
            key=self.key,
            text=self.text
        )

def h(tag: Optional[str], props: Optional[dict[str, Any]] = None, children: Optional[list[VNode]] = None, key: Optional[str] = None, text: Optional[str] = None) -> VNode:
    return VNode(
        tag=tag,
        props=props or {},
        children=children or [],
        key=key,
        text=text
    )

